package br.com.sistemacardapio.pedido;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController public class AnalyticsController{private final AnalyticsService s;public AnalyticsController(AnalyticsService s){this.s=s;}@PostMapping("/api/public/analytics/{slug}")@ResponseStatus(HttpStatus.NO_CONTENT)public void registrar(@PathVariable String slug,@RequestBody AnalyticsService.Evento r){s.registrar(slug,r);}@GetMapping("/api/analytics")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public Map<String,Object>resumo(){return s.resumo();}}
